INSERT INTO doom_constants (name, value, source) VALUES ('ACTIVE_SOUND_ODDS', 320.0d, 'A_Chase rolls P_Random()<3 per call and its see frames average ~5 tics, so about one tic in 400; this engine rolls per tic');
INSERT INTO doom_constants (name, value, source) VALUES ('AIM_SPREAD_DEGREES', 5.625d, '1<<26 in BAM, P_BulletSlope: autoaim tries straight ahead then this far either side');
INSERT INTO doom_constants (name, value, source) VALUES ('ATTACK_Z_OFFSET', 8.0d, '8*FRACUNIT, P_LineAttack: a shot leaves the eye this far above mid-height');
INSERT INTO doom_constants (name, value, source) VALUES ('AUTOAIM_SLOPE', 0.625d, '100*FRACUNIT/160, P_AimLineAttack: the vertical half-cone autoaim searches');
INSERT INTO doom_constants (name, value, source) VALUES ('AUTOMAP_MAX_ZOOM', 8.0d, 'Closest in the automap will go');
INSERT INTO doom_constants (name, value, source) VALUES ('AUTOMAP_MIN_ZOOM', 0.125d, 'Furthest out the automap will go');
INSERT INTO doom_constants (name, value, source) VALUES ('AUTOMAP_WORLD_HEIGHT', 2048.0d, 'Map units spanned by the screen height at zoom 1');
INSERT INTO doom_constants (name, value, source) VALUES ('BLOCKMAP_CELL', 128.0d, 'MAPBLOCKUNITS, p_local.h: the grid the thing-collision broad phase buckets into');
INSERT INTO doom_constants (name, value, source) VALUES ('BLOCK_MARGIN', 2.0d, 'this engine: slack on the bounding box that stands in for the blockmap');
INSERT INTO doom_constants (name, value, source) VALUES ('BOB_FACTOR', 4.0d, 'p_user.c: player->bob is the squared momentum >> 2');
INSERT INTO doom_constants (name, value, source) VALUES ('BOB_PERIOD_TICS', 20.0d, 'p_user.c: FINEANGLES/20*leveltime, so the bob repeats every 20 tics');
INSERT INTO doom_constants (name, value, source) VALUES ('BONUSADD', 6.0d, 'BONUSADD, p_local.h: the gold blink per item taken');
INSERT INTO doom_constants (name, value, source) VALUES ('CHASE_AXIS_DEADBAND', 10.0d, '10*FRACUNIT, P_NewChaseDir: nearer than this on an axis and that axis has no preference');
INSERT INTO doom_constants (name, value, source) VALUES ('CHASE_MOVECOUNT_MASK', 15.0d, 'P_TryWalk: movecount = P_Random()&15');
INSERT INTO doom_constants (name, value, source) VALUES ('CHASE_SWAP_CHANCE', 200.0d, 'P_NewChaseDir: P_Random() > 200 tries the other axis first');
INSERT INTO doom_constants (name, value, source) VALUES ('DAMAGE_FLOOR_INTERVAL', 32.0d, 'P_PlayerInSpecialSector: a damaging floor bites once every 32 tics');
INSERT INTO doom_constants (name, value, source) VALUES ('DEFAULT_ATTACK_RANGE', 2048.0d, 'MISSILERANGE, 32*64*FRACUNIT: how far a shot carries when the catalogue gives no range');
INSERT INTO doom_constants (name, value, source) VALUES ('DROPPED_THING_ID_BASE', 100000.0d, 'this engine: Things at or above this id were dropped by a monster, not placed by the WAD');
INSERT INTO doom_constants (name, value, source) VALUES ('EFFECT_ID_TIC_SPAN', 4096.0d, 'this engine: world_effects ids pack a tic into this many slots per source');
INSERT INTO doom_constants (name, value, source) VALUES ('FORWARDMOVE', 25.0d, '0x19, forwardmove[0], g_game.c');
INSERT INTO doom_constants (name, value, source) VALUES ('FORWARDMOVE_RUN', 50.0d, '0x32, forwardmove[1]');
INSERT INTO doom_constants (name, value, source) VALUES ('FRICTION', 0.90625d, '0xe800/65536, p_mobj.c: momentum kept per tic on the ground');
INSERT INTO doom_constants (name, value, source) VALUES ('GRAVITY', 1.0d, 'FRACUNIT, p_local.h: one unit a tic, squared');
INSERT INTO doom_constants (name, value, source) VALUES ('GUNSHOT_SPREAD_UNITS', 16384.0d, '(P_Random()-P_Random())<<18 as a fraction of a full turn, P_GunShot');
INSERT INTO doom_constants (name, value, source) VALUES ('HITSCAN_SPREAD_UNITS', 4096.0d, '(P_Random()-P_Random())<<20 as a fraction of a full turn, A_PosAttack');
INSERT INTO doom_constants (name, value, source) VALUES ('ITEM_FOG_EFFECT_ID_BASE', 4000000000.0d, 'this engine: the world_effects id range item respawns own');
INSERT INTO doom_constants (name, value, source) VALUES ('ITEM_RESPAWN_TICS', 1050.0d, '30*TICRATE, P_RespawnSpecials');
INSERT INTO doom_constants (name, value, source) VALUES ('MAXBOB', 16.0d, '0x100000, p_local.h: the view bob is clamped here');
INSERT INTO doom_constants (name, value, source) VALUES ('MAXMOVE', 30.0d, '30*FRACUNIT, p_local.h: momentum is clamped to this');
INSERT INTO doom_constants (name, value, source) VALUES ('MAXSTEP', 24.0d, '24*FRACUNIT, P_TryMove: the highest step a thing climbs');
INSERT INTO doom_constants (name, value, source) VALUES ('MELEE_REACH', 68.0d, 'this engine: MELEERANGE (64) plus a margin, one number for every biter');
INSERT INTO doom_constants (name, value, source) VALUES ('MESSAGE_TICS', 140.0d, 'HU_MSGTIMEOUT, 4*TICRATE: how long a pickup line stays up');
INSERT INTO doom_constants (name, value, source) VALUES ('MIN_WALK_OPENING', 56.0d, 'this engine: the opening anything needs to walk through, where vanilla P_Move uses the thing''s own height');
INSERT INTO doom_constants (name, value, source) VALUES ('MISSILE_SPAWN_AHEAD', 20.0d, 'this engine: a missile starts this far in front of its shooter so it cannot hit them');
INSERT INTO doom_constants (name, value, source) VALUES ('MISSILE_SPAWN_Z', 32.0d, '4*8*FRACUNIT, P_SpawnMissile: a missile leaves this far above the floor');
INSERT INTO doom_constants (name, value, source) VALUES ('MONSTER_RESPAWN_EFFECT_ID_BASE', 4100000000.0d, 'this engine: the range nightmare monster respawns own');
INSERT INTO doom_constants (name, value, source) VALUES ('MONSTER_RESPAWN_TICS', 420.0d, '12*TICRATE, P_NightmareRespawn');
INSERT INTO doom_constants (name, value, source) VALUES ('MONSTER_STEP', 8.0d, 'this engine: one walk stride for every monster, where vanilla uses mobjinfo speed');
INSERT INTO doom_constants (name, value, source) VALUES ('NIGHTMARE_MISSILE_SPEED', 20.0d, 'G_InitNew: fast missiles, every monster missile raised to this on Nightmare');
INSERT INTO doom_constants (name, value, source) VALUES ('PICKUP_REACH', 36.0d, 'P_TouchSpecialThing: the player radius plus an item radius');
INSERT INTO doom_constants (name, value, source) VALUES ('PLAYER_HEIGHT', 56.0d, 'mobjinfo MT_PLAYER height');
INSERT INTO doom_constants (name, value, source) VALUES ('PLAYER_RADIUS', 16.0d, 'mobjinfo MT_PLAYER radius');
INSERT INTO doom_constants (name, value, source) VALUES ('PLAYER_RESPAWN_EFFECT_ID_BASE', 4200000000.0d, 'this engine: the range deathmatch player respawns own');
INSERT INTO doom_constants (name, value, source) VALUES ('POS_EPSILON', 1e-07d, 'this engine: a float position within this of the last one counts as unmoved');
INSERT INTO doom_constants (name, value, source) VALUES ('PROJECTILE_EFFECT_ID_BASE', 3000000000000.0d, 'this engine: the world_effects id range projectile impacts own');
INSERT INTO doom_constants (name, value, source) VALUES ('PSPRITE_EPSILON', 0.001d, 'this engine: a psprite offset within this of its rest counts as at rest');
INSERT INTO doom_constants (name, value, source) VALUES ('PSPRITE_REST_X', 1.0d, 'p_pspr.c: the ready weapon rests at this sx');
INSERT INTO doom_constants (name, value, source) VALUES ('PSPRITE_REST_Y', 32.0d, 'WEAPONTOP, p_pspr.c: and at this sy');
INSERT INTO doom_constants (name, value, source) VALUES ('SHADOW_MISS_UNITS', 2048.0d, '<<21, the extra error a shot picks up against an MF_SHADOW target');
INSERT INTO doom_constants (name, value, source) VALUES ('SHADOW_SPREAD_UNITS', 4096.0d, '(P_Random()-P_Random())<<20 as a fraction of a full turn, MF_SHADOW aim');
INSERT INTO doom_constants (name, value, source) VALUES ('SIDEMOVE', 24.0d, '0x18, sidemove[0]');
INSERT INTO doom_constants (name, value, source) VALUES ('SIDEMOVE_RUN', 40.0d, '0x28, sidemove[1]');
INSERT INTO doom_constants (name, value, source) VALUES ('SIGHT_RANGE', 1200.0d, 'this engine: P_LookForPlayers has no range, this one does');
INSERT INTO doom_constants (name, value, source) VALUES ('SKULL_CHARGE_SPEED', 20.0d, 'SKULLSPEED, 20*FRACUNIT: A_SkullAttack hurls a lost soul this fast');
INSERT INTO doom_constants (name, value, source) VALUES ('SKULL_HIT_REACH', 36.0d, 'this engine: the box a charging lost soul lands its hit in');
INSERT INTO doom_constants (name, value, source) VALUES ('SLOPE_UNBOUNDED', 1000000.0d, 'this engine: stands in for an unlimited aim window before any line narrows it');
INSERT INTO doom_constants (name, value, source) VALUES ('SOUND_TRIM_AGE_TICS', 70.0d, 'Positional sound cues older than two seconds have been read by every client; the referee used to delete them once a second');
INSERT INTO doom_constants (name, value, source) VALUES ('SOUND_TRIM_INTERVAL_TICS', 35.0d, 'How often the trim runs, in tics -- once a second, as the referee timer did');
INSERT INTO doom_constants (name, value, source) VALUES ('STOPSPEED', 0.0625d, '0x1000/65536, p_mobj.c: below this a thing stands still');
INSERT INTO doom_constants (name, value, source) VALUES ('THRUST_UNIT', 0.03125d, '2048/65536: P_MovePlayer thrusts cmd->forwardmove*2048');
INSERT INTO doom_constants (name, value, source) VALUES ('TICRATE', 35.0d, '35 tics a second');
INSERT INTO doom_constants (name, value, source) VALUES ('TURN_DEGREES_PER_TIC', 3.2d, 'angleturn[1] 640<<16 per tic, g_game.c: the keyboard turn');
INSERT INTO doom_constants (name, value, source) VALUES ('USERANGE', 64.0d, '64*FRACUNIT, p_local.h: how far P_UseLines reaches');
INSERT INTO doom_constants (name, value, source) VALUES ('VIEWHEIGHT', 41.0d, '41*FRACUNIT, p_local.h: the eye above the floor');
